function countdown(t,e,n,r){let o=e*3600+n*60+r;const c=document.querySelector(`${t} .hour`);const l=document.querySelector(`${t} .minute`);const u=document.querySelector(`${t} .second`);const a=setInterval((()=>{if(o<=0){clearInterval(a);console.log("Time's up!");return}let t=Math.floor(o/3600);let e=Math.floor(o%3600/60);let n=o%60;c.innerText=String(t).padStart(2,"0");l.innerText=String(e).padStart(2,"0");u.innerText=String(n).padStart(2,"0");o--}),1e3)}